import{z as i,x as o,o as r,c as p,q as l,j as t,D as E,d as n,s as B,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"指数调入调出","description":"","frontmatter":{"title":"指数调入调出","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/index-rebalance.md","filePath":"quant/index-rebalance.md","lastUpdated":1791413859000}'),d={name:"quant/index-rebalance.md"};function h(u,a,m,D,f,c){const A=o("Mermaid");return r(),p("div",null,[a[2]||(a[2]=l('<h1 id="指数调入调出" tabindex="-1">指数调入调出 <a class="header-anchor" href="#指数调入调出" aria-label="Permalink to &quot;指数调入调出&quot;">​</a></h1><div class="epigraph"><p>调入日的被动买盘是可预期的订单，不是意外基本面；用生效后的成分回填历史因子宇宙，会把后来才进指数的公司当成一直可交易的大盘。</p><footer>—— 据 Shleifer, Journal of Finance, 1986；Wurgler and Zhuravskaya, Journal of Business, 2002 整理</footer></div><p>上一课<a href="/quant/merger-arb-event">并购套利</a>交易的是公司控制权事件。指数调入调出交易的是<strong>机械资金流</strong>：被动产品必须在生效日附近买调入、卖调出。本课补两件事：事件策略如何避免前视，以及因子宇宙不得用今日成分回填。不写指数编制手册全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Shleifer 记录标普调入伴随价格上涨，把需求曲线倾斜写进经验。Wurgler–Zhuravskaya 强调替代弹性有限时，指数买盘造成持续或半持续的价格压力。回测偏差有两条。事件策略：用最终生效名单在宣布前建仓，或假设能在生效日收盘按收盘价与全体被动资金同时成交——你没有那么多队首位置，这点留给 LOB，但本课至少不能用生效日 VWAP 当自己的成交且零冲击。因子宇宙：用当前指数成员往回切历史样本，丢掉调出与退市，又是幸存者，且偏向后来变大的公司。</p><p><span class="marginnote">「机械资金流」翻译过来就是「日历上写死的买卖」：规则定了名单，被动基金就得在生效日附近按新权重成交，不管价格。它和并购套利的区别在于：这里没有交易破裂风险，只有流动性风险。</span></p><p>财务课的行业分类与指数行业配额互动：调入常为了维持行业权重，分类键必须 PIT。</p><h3 id="调入不是盈利惊喜" tabindex="-1">调入不是盈利惊喜 <a class="header-anchor" href="#调入不是盈利惊喜" aria-label="Permalink to &quot;调入不是盈利惊喜&quot;">​</a></h3><p>价格上涨可以来自机械买盘，不必来自基本面改善。把调入后的回报当成质量或盈利因子的验证，会把被动流记进基本面 alpha。本课把指数事件从因子信息集里分开：宇宙可以用指数成员，但那是可投资定义，不是基本面信号。</p><p><span class="marginnote">初学者容易把调入当成「市场认可公司质量」的信号，把调入后的上涨记进盈利或质量因子。实际上那更可能只是被动买盘的价格压力；不把它从因子信息集里分开，因子回测就会把机械流错当 alpha。</span></p><p><span class="marginnote">宣布日与生效日之间常有数日到数周。纸面策略若两头都按收盘完美成交，等于既吃了宣布跳空又当自己是生效日的全部被动流。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事件：在宣布后第一可成交价按预期被动流的方向布局，或只交易宣布到生效之间的价差，预先声明。成交量受容量约束，用参与率上限，而不是全额指数权重。生效日附近冲击留给执行模型；本课要求至少扣一个惩罚或降低规模。因子：每个形成日用<strong>当时</strong>指数成分或当时全市场宇宙，调出公司在调出后离开指数宇宙，但仍按退市/上市规则留在全市场宇宙直到真正离开市场。</p><p>不要用后来才存在的指数（某主题指数 2020 年才发布）去切 2010 年样本还称为「当时可投资」。</p>',14)),(r(),t(s,null,{default:E(()=>[B(A,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANN%5B%22%E5%AE%A3%E5%B8%83%E6%97%A5%E5%90%8E%E5%8F%AF%E6%88%90%E4%BA%A4%22%5D%20--%3E%20WIN%5B%22%E5%AE%A3%E5%B8%83%E8%87%B3%E7%94%9F%E6%95%88%22%5D%0A%20%20WIN%20--%3E%20EFF%5B%22%E7%94%9F%E6%95%88%E6%97%A5%E8%A2%AB%E5%8A%A8%E6%B5%81%22%5D%0A%20%20NOW%5B%22%E4%BB%8A%E6%97%A5%E6%88%90%E5%88%86%E5%9B%9E%E5%A1%AB%22%5D%20--%3E%20SURV%5B%22%E6%8C%87%E6%95%B0%E5%B9%B8%E5%AD%98%E8%80%85%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"被动份额越大，生效日越不好当流动性提供者还假设自己吃满价差。回测用参与率上限（例如不超过当日成交的一个很小比例）截断规模，剩余信号视为无法实施。因子层面，形成日成分是可投资定义；调出股票若仍上市，可留在全市场宇宙，只是离开指数子集。不要把两条宇宙混称为同一个 HML。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"被动份额上升时，调入的价格压力变大，套利者需要更多资本去提供流动性。资金课的占用在这里是库存风险：你买调出、卖调入，等待生效日对手盘，期间有 beta 与借券。失败模式不是并购破裂，而是生效日流动性不足、停牌或涨跌停让被动流挤在可成交边上，价差不收敛。纸面收敛假设没有这条制度摩擦。",-1)),(r(),t(s,null,{default:E(()=>[B(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20E0%5B%22%E5%AE%A3%E5%B8%83%E6%97%A5%3A%20%E5%90%8D%E5%8D%95%E5%85%AC%E5%BC%80%22%5D%20--%3E%20INV%5B%22%E5%A5%97%E5%88%A9%E8%80%85%E5%BB%BA%E5%BA%93%E5%AD%98%3A%20%E9%A2%84%E5%85%88%E6%8C%81%E6%9C%89%E8%B0%83%E5%85%A5%20%2F%20%E8%B0%83%E5%87%BA%E8%85%BF%22%5D%0A%20%20INV%20--%3E%20HOLD%5B%22%E7%AD%89%E5%BE%85%E6%9C%9F%3A%20beta%20%E6%9A%B4%E9%9C%B2%20%2B%20%E5%80%9F%E5%88%B8%20%2B%20%E4%BF%9D%E8%AF%81%E9%87%91%E5%8D%A0%E7%94%A8%22%5D%0A%20%20HOLD%20--%3E%20EFF%5B%22%E7%94%9F%E6%95%88%E6%97%A5%3A%20%E8%A2%AB%E5%8A%A8%E5%AF%B9%E6%89%8B%E7%9B%98%E5%88%B0%E8%BE%BE%22%5D%0A%20%20EFF%20--%3E%20OK%7B%22%E5%8F%AF%E6%88%90%E4%BA%A4%E8%BE%B9%E7%95%85%E9%80%9A%3F%22%7D%0A%20%20OK%20--%3E%7C%22%E6%98%AF%22%7C%20SETTLE%5B%22%E4%BB%B7%E5%B7%AE%E6%94%B6%E6%95%9B%2C%20%E5%BA%93%E5%AD%98%E5%87%BA%E6%B8%85%22%5D%0A%20%20OK%20--%3E%7C%22%E5%81%9C%E7%89%8C%20%2F%20%E6%B6%A8%E8%B7%8C%E5%81%9C%22%7C%20STUCK%5B%22%E8%A2%AB%E5%8A%A8%E6%B5%81%E6%8C%A4%E5%9C%A8%E6%9D%BF%E4%B8%8A%2C%20%E4%BB%B7%E5%B7%AE%E4%B8%8D%E6%94%B6%E6%95%9B%22%5D%0A%20%20STUCK%20--%3E%20LOSS%5B%22%E7%AA%97%E5%8F%A3%E6%8B%89%E9%95%BF%3A%20%E5%BA%93%E5%AD%98%E9%A3%8E%E9%99%A9%E4%B8%8E%E8%B5%84%E9%87%91%E5%8D%A0%E7%94%A8%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">后课涨跌停会让「生效日必须成交」的被动账户把订单堆在涨停板上。套利回测若假设自己也在板上完全成交，是在与被动抢一个不可得的队列。</span></p><p>因子宇宙用形成日成分或当时全市场，不用今日成员回填。事件策略在宣布后开仓，生效日规模受参与率上限，不得按指数全额权重、零冲击、收盘完美成交。主题指数在发布日之前不存在，不能回切十年当「当时可投资」。调入回报与基本面因子分列，避免把被动流验证成盈利或质量。</p><p><span class="marginnote">「今日成分回填」可以类比按现在的班级名单去翻十年前的毕业照：照片里默认大家一直在班，中途转走的老同学从相册消失——留在名单里的自然是后来变大、活得久的公司，历史收益因此虚高。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不估计指数编制的全部规则，不写 ETF 申赎机制全文。下一课系统处理停牌与涨跌停。后课默认：指数宇宙按形成日成分；事件开仓在宣布后；生效日全额零冲击成交不合法。</p><p>后课涨跌停会让生效日被动单堆在板上。本课至少禁止全额零冲击。宇宙按形成日成分。调入回报不验证基本面因子。主题指数发布前不可回切。宣布日至生效日的价差策略，占用与借券按库存风险计，而不是按隔夜事件计。</p><p>后课默认指数宇宙按形成日成分，事件开仓在宣布后；生效日全额零冲击成交不合法。</p><p>宣布到生效之间若遇到停牌或涨跌停，被动流与套利单都堆在可成交边上。回测不得假设自己在板上与被动同时全额成交；规模按参与率截断后，剩余视为无法实施。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>调入调出是机械资金流，不是盈余意外。</li><li>今日成分回填历史 = 指数版幸存者。</li><li>宣布日与生效日是两个事件，不能两边都按完美收盘成交。</li><li>容量与借券约束使纸面收敛偏乐观。</li><li>因子可用当时成分当宇宙，但不可把调入回报记进基本面 alpha。</li><li>出处：Shleifer (1986)；Wurgler and Zhuravskaya (2002)。</li></ul>',10))])}const b=i(d,[["render",h]]);export{C as __pageData,b as default};
